            tree = scope[ACC_TREE] = []

        result = scope[glom](target, item_spec, scope)

        if result is SKIP:
            return SKIP
        if result is STOP:
            return STOP

        tree.append(result)
        return result

    else:
        # Regular spec - just apply it
        return scope[glom](target, spec, scope)
